"""Shared helpers for miner_1 factor research."""
import os
import numpy as np
import pandas as pd

CUT = pd.Timestamp("2026-07-15")
START = pd.Timestamp("2020-01-01")
SYMBOLS = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX",
