import numpy as np, pandas as pd
from scipy.stats import spearmanr

def daily_rho(a, b, min_names=4):
    n = min(a.shape[0], b.shape[0])
    vals = []
    for i in range(n):
        x, y = a[i], b[i]
        m = np.isfinite(x) & np.isfinite(y)
        if m.sum() >= min_names:
            r = spearmanr(x[m], y[m])[0]
            if np.isfinite(r): vals.append(r)
