def flat_rho(a, b, min_obs=30):
    n = min(a.shape[0], b.shape[0])
    m = np.isfinite(a[:n]) & np.isfinite(b[:n])
    if m.sum() < min_obs: return np.nan, int(m.sum())
    r = spearmanr(a[:n][m], b[:n][m])[0]
    return float(r), int(m.sum())

